type WheelWithTicks = WheelEvent & {
  wheelDeltaX?: number;
  wheelDeltaY?: number;
};

/** WheelEvent has no device type. Keep line/page scrolls, conventional wheel
 * notches, and the Ctrl+wheel events generated by pinch in the zoom path. */
export function isTrackpadSwipe(event: WheelWithTicks): boolean {
  if (event.deltaMode !== WheelEvent.DOM_DELTA_PIXEL || event.ctrlKey || event.metaKey
    || event.altKey || event.shiftKey || event.buttons) return false;
  if (event.deltaX === 0 && event.deltaY === 0) return false;

  const ticks = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.wheelDeltaX : event.wheelDeltaY;
  return !ticks || ticks % 120 !== 0;
}

/** Desktop browsers deliver trackpad pinch as a Ctrl+wheel event. Chromium
 * uses 100 pixels per unit of logarithmic scale. A zero delta can begin a pinch. */
export function trackpadPinchFactor(event: WheelEvent): number | null {
  if (!event.ctrlKey || event.deltaMode !== WheelEvent.DOM_DELTA_PIXEL || !Number.isFinite(event.deltaY)) return null;
  return Math.exp(-Math.max(-100, Math.min(100, event.deltaY)) / 100);
}
